import{_ as i,c as n,o as a,ai as t}from"./chunks/framework.BrjRfu4a.js";const h=JSON.parse('{"title":"Basics of Financial Markets | Basics of Financial Engineering | Financial Engineering","description":"This page will explore the definition of financial markets, their functions, main types, participants, characteristics of global financial markets, the theory of market efficiency, regulation of financial markets, and recent trends and future outlook.","frontmatter":{"title":"Basics of Financial Markets | Basics of Financial Engineering | Financial Engineering","description":"This page will explore the definition of financial markets, their functions, main types, participants, characteristics of global financial markets, the theory of market efficiency, regulation of financial markets, and recent trends and future outlook.","head":[["meta",{"property":"og:title","content":"Basics of Financial Markets | Basics of Financial Engineering | Financial Engineering"}],["meta",{"property":"og:description","content":"This page will explore the definition of financial markets, their functions, main types, participants, characteristics of global financial markets, the theory of market efficiency, regulation of financial markets, and recent trends and future outlook."}],["meta",{"property":"og:image","content":"/images/Financial-Engineering.png"}],["meta",{"property":"og:url","content":"https://risk-quant-haun.github.io/financial-engineering/basics/markets"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://risk-quant-haun.github.io/ko/financial-engineering/basics/markets"}],["link",{"rel":"alternate","hreflang":"en","href":"https://risk-quant-haun.github.io/financial-engineering/basics/markets"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://risk-quant-haun.github.io/ko/financial-engineering/basics/markets"}],["link",{"rel":"canonical","href":"https://risk-quant-haun.github.io/financial-engineering/basics/markets"}]],"date":"2025-02-05T00:00:00.000Z"},"headers":[],"relativePath":"financial-engineering/basics/markets.md","filePath":"en/financial-engineering/basics/markets.md"}'),r={name:"financial-engineering/basics/markets.md"};function s(o,e,l,c,d,f){return a(),n("div",null,e[0]||(e[0]=[t('<h1 id="basics-of-financial-markets" tabindex="-1">Basics of Financial Markets <a class="header-anchor" href="#basics-of-financial-markets" aria-label="Permalink to &quot;Basics of Financial Markets&quot;">​</a></h1><p><strong>Basics of Financial Engineering | 2025.02.05</strong></p><p><strong>Financial markets are important economic infrastructures that enable the efficient allocation of capital by connecting suppliers and demanders of funds.</strong></p><p><strong>Various theories and techniques in financial engineering operate within these financial markets, and understanding the characteristics and structure of the market is an essential foundation for learning financial engineering.</strong></p><p><strong>This page will explore the definitions, functions, main types, participants, characteristics of global financial markets, theories of market efficiency, regulation of financial markets, as well as recent trends and future outlook.</strong></p><h2 id="_1️⃣-definition-and-functions-of-financial-markets" tabindex="-1">1️⃣ Definition and Functions of Financial Markets <a class="header-anchor" href="#_1️⃣-definition-and-functions-of-financial-markets" aria-label="Permalink to &quot;1️⃣ Definition and Functions of Financial Markets&quot;">​</a></h2><p>Financial markets are markets that provide a mechanism for the transfer of funds from economic agents with surplus funds (savers) to those with a shortage of funds (borrowers). This does not merely refer to a place of transaction but encompasses the entire system in which the prices of various financial products are determined and traded.</p><p>The main functions of financial markets are as follows:</p><div class="tip custom-block"><p class="custom-block-title">Core Functions of Financial Markets</p><ul><li><p><strong>Efficient Allocation of Resources</strong><br> Financial markets provide a channel to convert savings into productive investments, thereby enhancing the efficiency of resource allocation across the economy. They promote economic growth through mechanisms that direct funds to their most valued uses.</p></li><li><p><strong>Price Discovery</strong><br> They offer a process for discovering the &#39;fair value&#39; of financial assets through the collective intelligence and information of market participants. This serves as an important signal for the decision-making of economic agents.</p></li><li><p><strong>Liquidity Provision</strong><br> By providing an environment for investors to easily convert assets into cash when needed, they facilitate long-term investments and support capital formation.</p></li><li><p><strong>Risk Management and Diversification</strong><br> They offer mechanisms through various financial products and derivatives that allow economic agents to manage and diversify risks.</p></li><li><p><strong>Mitigation of Information Asymmetry</strong><br> By disseminating information through market prices and trading activities, they help reduce the information gap among market participants.</p></li><li><p><strong>Market Signal Transmission</strong><br> The price fluctuations in financial markets provide important signals regarding economic conditions, policy effects, future prospects, and more.</p></li></ul></div><p>These functions are interrelated, and when the financial system operates efficiently, it contributes to the overall stability and growth of the economy.</p><h2 id="_2️⃣-major-types-of-financial-markets" tabindex="-1">2️⃣ Major Types of Financial Markets <a class="header-anchor" href="#_2️⃣-major-types-of-financial-markets" aria-label="Permalink to &quot;2️⃣ Major Types of Financial Markets&quot;">​</a></h2><p>Financial markets can be classified into various types based on different criteria. Here, we will look at the most common classification methods.</p><h3 id="classification-by-maturity" tabindex="-1">Classification by Maturity <a class="header-anchor" href="#classification-by-maturity" aria-label="Permalink to &quot;Classification by Maturity&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Classification of Financial Markets by Maturity</p><ul><li><p><strong>Money Market</strong><br> This is a market where short-term (generally within one year) financial instruments are traded. Major trading instruments include Commercial Paper (CP), Certificates of Deposit (CD), Repurchase Agreements (Repo), and short-term government bonds. This market plays a crucial role in managing short-term liquidity for companies and financial institutions.</p></li><li><p><strong>Capital Market</strong><br> This is a market where medium to long-term (generally over one year) financial instruments are traded. Representative products include stocks, bonds, and long-term government bonds. The capital market plays an important role in corporate long-term financing and the long-term asset formation of investors.</p></li></ul></div><h3 id="classification-by-transaction-timing" tabindex="-1">Classification by Transaction Timing <a class="header-anchor" href="#classification-by-transaction-timing" aria-label="Permalink to &quot;Classification by Transaction Timing&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Classification of Financial Markets by Transaction Timing</p><ul><li><p><strong>Spot Market</strong><br> This is a market where the trading and settlement of financial instruments occur almost simultaneously. Most transactions in the stock market and bond market fall under this category.</p></li><li><p><strong>Futures or Forward Market</strong><br> This is a market where contracts are traded that promise to buy or sell an asset at a predetermined price at a specific point in the future. This plays a crucial role in managing price risk.</p></li></ul></div><h3 id="classification-by-product-type" tabindex="-1">Classification by Product Type <a class="header-anchor" href="#classification-by-product-type" aria-label="Permalink to &quot;Classification by Product Type&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Financial Market Classification by Product Type</p><ul><li><p><strong>Stock Market</strong><br> A market where shares representing ownership in a company are traded. Investors can acquire a portion of ownership in a company through the purchase of shares and can earn income in the form of dividends and capital gains.</p></li><li><p><strong>Bond Market</strong><br> A market where debt securities issued by governments, public institutions, and corporations are traded. Investors earn income through regular interest payments and the repayment of principal at maturity.</p></li><li><p><strong>Derivatives Market</strong><br> A market where financial contracts based on the value of underlying assets (such as stocks, bonds, commodities, interest rates, and exchange rates) are traded. Various products, including options, futures, and swaps, are available and are used for purposes such as hedging, speculation, and arbitrage.</p></li><li><p><strong>Forex Market</strong><br> A market where various currencies are traded, making it the most liquid and highest volume financial market in the world. It operates 24 hours globally and is an important venue where exchange rates are determined.</p></li><li><p><strong>Commodity Market</strong><br> A market where physical assets such as crude oil, gold, and agricultural products are traded. The commodity futures market provides producers and consumers with a means to manage price risk.</p></li></ul></div><h3 id="classification-by-trading-method" tabindex="-1">Classification by Trading Method <a class="header-anchor" href="#classification-by-trading-method" aria-label="Permalink to &quot;Classification by Trading Method&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Financial Market Classification by Trading Method</p><ul><li><p><strong>Exchange-Traded Market</strong><br> A market where trading occurs on formal exchanges with standardized rules and centralized clearing systems. Stock exchanges and futures exchanges fall into this category.</p></li><li><p><strong>Over-The-Counter (OTC) Market</strong><br> A market where trading occurs through direct negotiations between participants without going through exchanges. Customized derivatives, certain bonds, and foreign exchange trading primarily take place in the OTC market.</p></li></ul></div><p>These diverse financial markets are interconnected, and the prices and trading activities of each market affect other markets. Financial engineering plays an important role in understanding and modeling the interconnections and interactions between these markets.</p><h2 id="_3️⃣-key-participants-in-financial-markets" tabindex="-1">3️⃣ Key Participants in Financial Markets <a class="header-anchor" href="#_3️⃣-key-participants-in-financial-markets" aria-label="Permalink to &quot;3️⃣ Key Participants in Financial Markets&quot;">​</a></h2><p>Financial markets consist of various participants with different purposes and roles. Their interactions shape market dynamics and influence price determination.</p><div class="danger custom-block"><p class="custom-block-title">Key Participants in Financial Markets</p><ul><li><p><strong>Individual Investors</strong><br> Individuals who seek to grow their assets by investing their savings, participating in the market through financial intermediaries such as brokerages or banks. Recently, the development of online platforms and mobile apps has made direct investing easier.</p></li><li><p><strong>Institutional Investors</strong><br> Professional investment institutions that pool funds from others for management, including pension funds, mutual funds, hedge funds, insurance companies, and endowments. They have significant influence in the market due to their large-scale capital and expertise.</p></li><li><p><strong>Government and Public Institutions</strong><br> They participate in financial markets through funding via the issuance of government bonds, executing monetary policy, and implementing market stabilization measures. Central banks are crucial participants that directly affect market interest rates through monetary policy.</p></li><li><p><strong>Corporations</strong><br> They raise funds through issuing stocks and bonds and participate in the financial market through activities such as managing excess funds, hedging against exchange rate risks, and mergers and acquisitions (M&amp;A).</p></li><li><p><strong>Financial Intermediaries</strong><br> Banks, brokerages, asset management firms, and others play a role in connecting fund providers and demanders. They offer a variety of services such as investment advice, trade execution, liquidity provision, and market making.</p></li><li><p><strong>Market Makers</strong><br> They provide liquidity to the market by continuously quoting buy and sell prices for specific financial products. They earn profits through the bid-ask spread.</p></li><li><p><strong>Algorithmic Traders</strong><br> Participants who use computer algorithms to execute automated trading strategies, whose share in the market has significantly increased recently. High-frequency trading (HFT) falls into this category.</p></li><li><p><strong>Regulatory Agencies</strong><br> Institutions that establish and supervise rules to maintain fairness, transparency, and stability in financial markets, such as Korea’s Financial Services Commission, Financial Supervisory Service, and the U.S. SEC and CFTC.</p></li></ul></div><p>Each participant has different information, goals, constraints, and time horizons, and this diversity creates market dynamics. Financial engineering provides methodologies to model and analyze the behaviors and interactions of these diverse participants.</p><h2 id="_4️⃣-characteristics-of-the-global-financial-market" tabindex="-1">4️⃣ Characteristics of the Global Financial Market <a class="header-anchor" href="#_4️⃣-characteristics-of-the-global-financial-market" aria-label="Permalink to &quot;4️⃣ Characteristics of the Global Financial Market&quot;">​</a></h2><p>The modern financial market has evolved into a global network that transcends borders, which has increased the complexity of the environment that financial engineering must address.</p><div class="tip custom-block"><p class="custom-block-title">Key Characteristics of the Global Financial Market</p><ul><li><p><strong>24-Hour Trading Environment</strong><br> A trading environment has been created that allows for nearly continuous trading almost 24 hours a day, as financial centers around the world are interconnected. In particular, the foreign exchange market operates 24 hours a day by leveraging the time differences of major financial centers such as New York, London, and Tokyo.</p></li><li><p><strong>Increased Interconnectivity</strong><br> The development of information technology and financial innovation has greatly increased the connectivity among various countries and markets. This can lead to a &#39;contagion effect&#39; where shocks in one market quickly spread to others.</p></li><li><p><strong>Acceleration of Capital Movements</strong><br> Easing of capital controls and the development of digital finance have made cross-border capital movements much faster and easier. While this contributes to economic development, it also increases the risk of instability due to rapid capital inflows and outflows.</p></li><li><p><strong>Possibility of Regulatory Arbitrage</strong><br> The differences in financial regulatory environments among countries have made &#39;regulatory arbitrage&#39; possible. Financial institutions sometimes relocate specific activities to countries or regions with less stringent regulations.</p></li><li><p><strong>Importance of International Standards</strong><br> The importance of international standards and norms, such as the Basel Accords and IFRS (International Financial Reporting Standards), has increased for the stable operation of the global financial market.</p></li><li><p><strong>Globalization of Financial Crises</strong><br> As seen in the 2008 global financial crisis, an environment has been created where a financial crisis that starts in one country or region can quickly spread worldwide.</p></li><li><p><strong>Diverse Market Participants</strong><br> The entry of various global participants, such as sovereign wealth funds (SWFs), global hedge funds, and multinational financial institutions, has made market dynamics more complex.</p></li></ul></div><p>These characteristics of the global financial market have increased the necessity for financial engineering to develop more complex and sophisticated analytical tools and models. In particular, methodologies for risk management that consider interconnectivity and interdependence among countries and markets are becoming increasingly important.</p><h2 id="_5️⃣-market-efficiency-theory" tabindex="-1">5️⃣ Market Efficiency Theory <a class="header-anchor" href="#_5️⃣-market-efficiency-theory" aria-label="Permalink to &quot;5️⃣ Market Efficiency Theory&quot;">​</a></h2><p>An important theoretical framework for understanding how financial markets operate is the Efficient Market Hypothesis (EMH). This theory serves as the foundation for many models and analytical methodologies in financial engineering and was formalized by Professor Eugene Fama.</p><div class="warning custom-block"><p class="custom-block-title">Three Forms of Market Efficiency</p><ul><li><p><strong>Weak Form Efficiency</strong><br> This asserts that market prices already reflect all past price information and trading volume information. In this form, generating excess returns through the analysis of past price patterns (technical analysis) is impossible.</p></li><li><p><strong>Semi-Strong Form Efficiency</strong><br> This asserts that market prices reflect not only past information but also all publicly available information (such as corporate disclosures, economic indicators, news, etc.). In this form, generating excess returns through the analysis of public information (fundamental analysis) is impossible.</p></li><li><p><strong>Strong Form Efficiency</strong><br> This is the most extreme assertion that market prices reflect all relevant information, including insider information as well as public information. In this form, no investor can consistently outperform the market.</p></li></ul></div><h3 id="the-meaning-of-market-efficiency-theory" tabindex="-1">The Meaning of Market Efficiency Theory <a class="header-anchor" href="#the-meaning-of-market-efficiency-theory" aria-label="Permalink to &quot;The Meaning of Market Efficiency Theory&quot;">​</a></h3><p>The market efficiency theory provides important implications for the fields of financial markets and financial engineering:</p><div class="danger custom-block"><p class="custom-block-title">Meaning of Market Efficiency Theory</p><ul><li><p><strong>Effect of Information Reflection in Prices</strong><br> In an efficient market, prices are the best estimate of the expected value of an asset. When new information arrives, the market quickly incorporates it into prices.</p></li><li><p><strong>Random Walk Theory</strong><br> In an efficient market, price movements are unpredictable and random. This is because new information arrives unpredictably.</p></li><li><p><strong>Basis for Passive Investment Strategies</strong><br> If consistently beating the market is difficult, it may be rational to adopt passive investment strategies that track market indices. This forms the theoretical basis for index funds and ETFs.</p></li><li><p><strong>Arbitrage Infeasibility</strong><br> In a fully efficient market, risk-free arbitrage opportunities do not exist, or if they do, they disappear within a very short time.</p></li></ul></div><h3 id="challenges-and-anomalies-to-market-efficiency" tabindex="-1">Challenges and Anomalies to Market Efficiency <a class="header-anchor" href="#challenges-and-anomalies-to-market-efficiency" aria-label="Permalink to &quot;Challenges and Anomalies to Market Efficiency&quot;">​</a></h3><p>In real financial markets, several &quot;anomalies&quot; have been observed that do not align with the predictions of market efficiency theory:</p><div class="tip custom-block"><p class="custom-block-title">Market Anomalies</p><ul><li><p><strong>Momentum Effect</strong><br> Well-performing assets tend to continue to show strong performance in the short term.</p></li><li><p><strong>Value Effect</strong><br> Assets priced lower relative to their fundamental value (such as book value) tend to show higher returns in the long term.</p></li><li><p><strong>Small Firm Effect</strong><br> Stocks of small firms tend to exhibit higher risk-adjusted returns compared to large firms.</p></li><li><p><strong>Seasonal Effects</strong><br> There are specific price patterns that recur at certain times, such as the January effect and weekend effect.</p></li><li><p><strong>Excess Volatility</strong><br> The volatility of market prices is often much greater than the volatility of fundamental values (such as dividends).</p></li></ul></div><p>These anomalies have led to the development of a new research field called Behavioral Finance. Behavioral finance studies the impact of psychological elements, such as cognitive biases, emotions, and social influences, on financial markets.</p><p>Financial engineers are working to understand the balance between market efficiency and inefficiency and to develop various models and strategies that reflect this understanding.</p><h2 id="_6️⃣-regulation-of-financial-markets" tabindex="-1">6️⃣ Regulation of Financial Markets <a class="header-anchor" href="#_6️⃣-regulation-of-financial-markets" aria-label="Permalink to &quot;6️⃣ Regulation of Financial Markets&quot;">​</a></h2><p>Financial markets play a crucial role in the stability and efficiency of the economic system, thus requiring appropriate regulation and supervision. Financial regulation also significantly influences the scope and methods of financial engineering.</p><h3 id="purpose-of-financial-regulation" tabindex="-1">Purpose of Financial Regulation <a class="header-anchor" href="#purpose-of-financial-regulation" aria-label="Permalink to &quot;Purpose of Financial Regulation&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Main Purposes of Financial Regulation</p><ul><li><p><strong>Maintaining Financial Stability</strong><br> Reduces systemic risks and prevents the occurrence and spread of financial crises.</p></li><li><p><strong>Protecting Investors</strong><br> Protects individual investors from unfair treatment in situations of asymmetric information.</p></li><li><p><strong>Ensuring Market Integrity</strong><br> Maintains fairness and trust in the market by preventing unfair practices such as insider trading and market manipulation.</p></li><li><p><strong>Preventing Financial Crimes</strong><br> Prevents criminal activities that exploit the financial system, such as money laundering and terrorism financing.</p></li><li><p><strong>Consumer Protection</strong><br> Ensures transparency in financial products and services and protects the rights and interests of financial consumers.</p></li></ul></div><h3 id="key-areas-of-financial-regulation" tabindex="-1">Key Areas of Financial Regulation <a class="header-anchor" href="#key-areas-of-financial-regulation" aria-label="Permalink to &quot;Key Areas of Financial Regulation&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Key Areas of Financial Regulation</p><ul><li><p><strong>Capital Adequacy Regulation</strong><br> Regulations that require financial institutions to hold sufficient capital, such as the Basel Accords. This enhances the institutions&#39; ability to absorb risks.</p></li><li><p><strong>Market Conduct Regulation</strong><br> Regulations that promote fair trading practices and prohibit unfair activities such as market manipulation and insider trading.</p></li><li><p><strong>Information Disclosure Requirements</strong><br> Regulations that mandate appropriate information disclosure by companies and financial institutions, enabling investors to make informed decisions.</p></li><li><p><strong>Consumer Protection Regulation</strong><br> Regulations that protect financial consumers by ensuring the suitability of financial products, providing transparent information, and preventing unfair contract terms.</p></li><li><p><strong>Systemic Risk Management</strong><br> Macroprudential regulations aimed at maintaining the overall stability of the financial system, strengthened after the 2008 financial crisis.</p></li><li><p><strong>Derivatives Market Regulation</strong><br> Regulations aimed at increasing transparency in OTC derivatives and promoting trading through central clearinghouses (CCPs).</p></li></ul></div><h3 id="relationship-between-regulation-and-financial-engineering" tabindex="-1">Relationship Between Regulation and Financial Engineering <a class="header-anchor" href="#relationship-between-regulation-and-financial-engineering" aria-label="Permalink to &quot;Relationship Between Regulation and Financial Engineering&quot;">​</a></h3><p>Financial regulation significantly impacts financial engineering:</p><div class="tip custom-block"><p class="custom-block-title">Relationship Between Regulation and Financial Engineering</p><ul><li><p><strong>Cost of Regulatory Compliance</strong><br> As the costs to meet regulatory requirements increase, financial engineering is evolving in a way that enhances regulatory efficiency.</p></li><li><p><strong>Development of Risk Management Models</strong><br> The development of internal models to meet the risk management standards required by regulatory agencies has become a key application area of financial engineering.</p></li><li><p><strong>Balancing Innovation and Regulation</strong><br> Financial engineering seeks ways to enable innovation within the regulatory environment, sometimes leading to financial innovations that exploit regulatory gaps (regulatory arbitrage).</p></li><li><p><strong>Advancement of Regulatory Technology (RegTech)</strong><br> Financial engineering contributes to the development of &#39;RegTech,&#39; which are technical solutions that streamline regulatory compliance.</p></li></ul></div><h2 id="_7️⃣-recent-trends-and-future-outlook-in-financial-markets" tabindex="-1">7️⃣ Recent Trends and Future Outlook in Financial Markets <a class="header-anchor" href="#_7️⃣-recent-trends-and-future-outlook-in-financial-markets" aria-label="Permalink to &quot;7️⃣ Recent Trends and Future Outlook in Financial Markets&quot;">​</a></h2><p>Financial markets are constantly evolving in response to technological advancements, changes in economic structures, and social demands. In the field of financial engineering, new theories and methodologies are continually being developed to address these changes.</p><h3 id="recent-key-trends-in-financial-markets" tabindex="-1">Recent Key Trends in Financial Markets <a class="header-anchor" href="#recent-key-trends-in-financial-markets" aria-label="Permalink to &quot;Recent Key Trends in Financial Markets&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Key Trends in Financial Markets</p><ul><li><p><strong>Digital Transformation</strong><br> The rise of fintech companies and the digital innovation of existing financial institutions are fundamentally changing the way financial services are provided. New financial services such as mobile banking, robo-advisors, and P2P lending have emerged.</p></li><li><p><strong>Spread of Algorithmic Trading</strong><br> Automated trading using computer algorithms now accounts for a significant portion of market trading volume. In particular, high-frequency trading occurs at speeds measured in milliseconds.</p></li><li><p><strong>Increase in Passive Investment</strong><br> With a significant rise in passive investment strategies through index funds and ETFs, new impacts on market price formation mechanisms and market efficiency are observed.</p></li><li><p><strong>Emergence of Sustainable Finance</strong><br> As investments that consider ESG (Environmental, Social, Governance) factors expand, the financial performance of companies, as well as their social and environmental impacts, become important evaluation criteria.</p></li><li><p><strong>Decentralized Finance (DeFi) and Crypto Assets</strong><br> The emergence of a decentralized finance ecosystem based on blockchain technology and various crypto assets poses challenges to traditional financial intermediation functions.</p></li><li><p><strong>Data-Driven Finance</strong><br> Data analysis utilizing big data, artificial intelligence, and machine learning is becoming increasingly important across all areas of finance, including investment decisions, risk management, and customer service.</p></li><li><p><strong>Expansion of Cross-Border Financial Services</strong><br> The advancement of digital technology has made it easier to provide financial services that transcend borders, accelerating the integration of the global financial market.</p></li></ul></div><h3 id="directions-for-the-development-of-future-financial-markets" tabindex="-1">Directions for the Development of Future Financial Markets <a class="header-anchor" href="#directions-for-the-development-of-future-financial-markets" aria-label="Permalink to &quot;Directions for the Development of Future Financial Markets&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">Directions for the Development of Future Financial Markets</p><ul><li><p><strong>Enhancement of Financial Inclusion</strong><br> With technological advancements allowing marginalized groups in traditional financial systems to access financial services, financial inclusion will expand.</p></li><li><p><strong>Personalized Financial Services</strong><br> Financial products and services tailored to individual needs, utilizing big data and artificial intelligence, are expected to become more sophisticated.</p></li><li><p><strong>Deepening Integration of Finance and Technology</strong><br> As the boundaries between finance and technology become increasingly blurred, financial services will evolve into an &quot;Embedded Finance&quot; model, integrated with other services.</p></li><li><p><strong>Evolution of Regulatory Environment</strong><br> Regulatory frameworks will continue to evolve in response to new financial technologies and services, with innovation-friendly approaches such as &quot;regulatory sandboxes&quot; becoming more prevalent.</p></li><li><p><strong>Emergence of Central Bank Digital Currencies (CBDCs)</strong><br> Central banks in various countries are reviewing or piloting digital currency issuance, which could bring significant changes to financial systems and monetary policies.</p></li><li><p><strong>Impact of Quantum Computing</strong><br> As quantum computing technology advances, there is potential for revolutionary changes in various areas of the financial market, including financial modeling, optimization, and encryption.</p></li><li><p><strong>Climate Change and Finance</strong><br> As the impact of climate change on financial markets and asset values becomes more significant, the analysis and management of climate-related financial risks will become a core element of the financial system.</p></li></ul></div><p>These trends and directions will present new challenges and opportunities for financial engineering, making it increasingly important to develop effective models and tools in a more complex and interconnected financial environment.</p><h2 id="_8️⃣-conclusion-the-importance-of-understanding-financial-markets" tabindex="-1">8️⃣ Conclusion: The Importance of Understanding Financial Markets <a class="header-anchor" href="#_8️⃣-conclusion-the-importance-of-understanding-financial-markets" aria-label="Permalink to &quot;8️⃣ Conclusion: The Importance of Understanding Financial Markets&quot;">​</a></h2><p><strong>Financial markets play a central role in the modern economy and possess complex and dynamic characteristics. A deep understanding of the structure, function, participants, and operating principles of these financial markets is essential for effectively learning and applying financial engineering.</strong></p><p>Understanding financial markets is important for the following reasons:</p><div class="tip custom-block"><p class="custom-block-title">Importance of Understanding Financial Markets</p><ul><li><p><strong>Contextualizing Models</strong><br> Financial engineering models must reflect the realities of financial markets, making it crucial to understand the market&#39;s characteristics and constraints.</p></li><li><p><strong>Assessing the Appropriateness of Assumptions</strong><br> Many financial models are based on specific assumptions regarding market efficiency, liquidity, transaction costs, etc. Understanding the actual market environment is necessary to evaluate the appropriateness of these assumptions.</p></li><li><p><strong>Identifying and Measuring Risks</strong><br> Identifying and measuring various financial risks, such as market risk, liquidity risk, and credit risk, requires insights into market structure and dynamics.</p></li><li><p><strong>Predicting the Direction of Innovation</strong><br> By understanding trends and developments in financial markets, it is possible to predict and develop the financial engineering techniques and models needed in the future.</p></li><li><p><strong>Considering Ethical and Social Impacts</strong><br> Financial markets are not just technical systems but part of the socioeconomic structure, making it important to consider the ethical and social impacts of applying financial engineering.</p></li></ul></div><p><strong>In the upcoming foundational series on financial engineering, we will delve more deeply into core topics of financial engineering such as various financial products, options pricing theory, portfolio theory, risk management, and time series analysis based on this fundamental understanding of financial markets.</strong></p><p><strong>As financial markets are constantly changing, it is important for finance professionals and financial engineers to remain vigilant to market changes and develop the ability to adapt. This will contribute to more effective financial decision-making and the development of innovative financial solutions.</strong></p><h2 id="_9️⃣-references-and-recommended-materials" tabindex="-1">9️⃣ References and Recommended Materials <a class="header-anchor" href="#_9️⃣-references-and-recommended-materials" aria-label="Permalink to &quot;9️⃣ References and Recommended Materials&quot;">​</a></h2><p>For a deeper understanding of financial markets, the following materials may be helpful:</p><div class="warning custom-block"><p class="custom-block-title"><strong>Recommended Books</strong></p><ul><li>&quot;Financial Market Theory&quot; (Kim Jong-seon, Park Youngsa)</li><li>&quot;Understanding Global Financial Markets&quot; (Ahn Chang-guk, Shin Yeongsa)</li><li>&quot;Financial Markets and Institutions&quot; (Frederic S. Mishkin, Stanley G. Eakins)</li><li>&quot;The Economics of Money, Banking, and Financial Markets&quot; (Frederic S. Mishkin)</li><li>&quot;A Random Walk Down Wall Street&quot; (Burton G. Malkiel)</li><li>&quot;Efficiently Inefficient: How Smart Money Invests and Market Prices Are Determined&quot; (Lasse Heje Pedersen)</li></ul></div><div class="danger custom-block"><p class="custom-block-title"><strong>Online Resources</strong></p><ul><li>Bank of Korea Economic Education Portal: <a href="https://www.bokeducation.or.kr/" target="_blank" rel="noreferrer">https://www.bokeducation.or.kr/</a></li><li>Financial Supervisory Service Financial Education Center: <a href="https://www.fss.or.kr/edu/" target="_blank" rel="noreferrer">https://www.fss.or.kr/edu/</a></li><li>Coursera: Financial Markets (Yale University): <a href="https://www.coursera.org/learn/financial-markets-global" target="_blank" rel="noreferrer">https://www.coursera.org/learn/financial-markets-global</a></li><li>Khan Academy - Finance and Capital Markets: <a href="https://www.khanacademy.org/economics-finance-domain/core-finance" target="_blank" rel="noreferrer">https://www.khanacademy.org/economics-finance-domain/core-finance</a></li></ul></div><div class="tip custom-block"><p class="custom-block-title"><strong>Major Financial Information Sites</strong></p><ul><li>Bloomberg: <a href="https://www.bloomberg.com/" target="_blank" rel="noreferrer">https://www.bloomberg.com/</a></li><li>Financial Times: <a href="https://www.ft.com/" target="_blank" rel="noreferrer">https://www.ft.com/</a></li><li>The Wall Street Journal: <a href="https://www.wsj.com/" target="_blank" rel="noreferrer">https://www.wsj.com/</a></li><li>Korea Exchange: <a href="https://www.krx.co.kr/" target="_blank" rel="noreferrer">https://www.krx.co.kr/</a></li><li>Korea Financial Investment Association: <a href="https://www.kofia.or.kr/" target="_blank" rel="noreferrer">https://www.kofia.or.kr/</a></li></ul></div><div class="info custom-block"><p class="custom-block-title"><strong>Disclaimer</strong></p><ul><li>The content of this blog is written for educational and informational purposes and should not be considered an investment recommendation or a substitute for financial advice. For actual financial decisions, please seek the advice of a professional.</li></ul></div>',68)]))}const m=i(r,[["render",s]]);export{h as __pageData,m as default};
